func _flight_log_sample(sample:Dictionary)->Dictionary:
	# Full current/last contexts and the explicit comparison event retain the
	# complete measurement. Repeating it every two seconds would exceed the
	# existing bounded logger line size and discard the entire flight sample.
	var result:=sample.duplicate(true)
	var measurement:Variant=sample.get("last_surface_alignment",{})
	if measurement is Dictionary and not measurement.is_empty():
		var compact:Dictionary={"compact_periodic_record":true}
		for key:String in ["ok","diagnostic_only","response_applied","delta_m","context_binding_sha256","observed_elapsed_days"]:
			if measurement.has(key):compact[key]=measurement[key]
		if not measurement.get("ok",false):compact["reason"]=str(measurement.get("reason","unavailable"))
		var context:Variant=measurement.get("query_context",{})
		if context is Dictionary:
			compact["query_context"]={}
			for key:String in ["body_id","parent_uid_u32","frame_index"]:
				if context.has(key):compact.query_context[key]=context[key]
		result["last_surface_alignment"]=compact
	var footprint:Variant=sample.get("last_surface_footprint",{})
	if footprint is Dictionary and not footprint.is_empty():
		# The complete observation stays in both report contexts. A stable
		# reference fits the existing bounded periodic log alongside the older
		# natural/spherical observations, even for a three-volume Cobra walk.
		result["last_surface_footprint"]={"compact_periodic_record":true,"report_sha256":JSON.stringify(footprint).sha256_text()}
		if measurement is Dictionary and not measurement.is_empty():
			var reference:Dictionary={"compact_periodic_record":true}
			for key:String in ["context_binding_sha256","delta_m","observed_elapsed_days"]:
				if measurement.has(key):reference[key]=measurement[key]
			result["last_surface_alignment"]=reference
	var geometry:Variant=sample.get("last_contact_geometry",{})
	result.erase("last_contact_geometry")
	if geometry is Dictionary and not geometry.is_empty():
		# One shallow reference table keeps all three full observations in the
		# report without overflowing the unchanged periodic logger line cap.
		var references:Dictionary={"contact_geometry_sha256":JSON.stringify(geometry).sha256_text()}
		for key:String in ["last_surface_alignment","last_surface_footprint"]:
			var observation:Variant=sample.get(key,{})
			if observation is Dictionary and not observation.is_empty():references[key+"_sha256"]=JSON.stringify(observation).sha256_text()
			result.erase(key)
		result["diagnostic_observation_refs"]=references
	return result
