	var backup_payload:=_payload()
	if backup_payload.is_empty():_menu_text("Расчёт касания не завершён: новый код не создан. Здесь можно вставить прежний исправный код для восстановления.")
	backup_edit=TextEdit.new();backup_edit.custom_minimum_size=Vector2(900,230);backup_edit.add_theme_font_size_override("font_size",settings.reading_size);backup_edit.text="" if backup_payload.is_empty() else saves.encode(backup_payload,0);menu_rows.add_child(backup_edit)
	_menu_action("Копировать код",func():
		if backup_edit.text.is_empty():_announce("Новый код пока недоступен.");return
		DisplayServer.clipboard_set(backup_edit.text);_announce("Код резервной копии скопирован."))
	_menu_action("Вставить из буфера",func():backup_edit.text=DisplayServer.clipboard_get())
	_menu_action("Восстановить из кода",_import_backup)
	if not _latest_hyperdrive_backup().is_empty():_menu_action("Сохранение до перехода на исходный двигатель",_show_previous_hyperdrive_backup)
func _import_backup()->void:
	if busy:return
	if not graphics_return.is_empty():_announce("Сначала вернитесь к основному полёту через меню.");return
	var entry:Dictionary=saves.decode(backup_edit.text)
	var loaded:Dictionary={} if entry.is_empty() else _decode_state(entry.payload)
	if loaded.is_empty():_announce("Код повреждён или несовместим. Текущий полёт не изменён.");return
	if loaded.surface is NativeSurface or loaded.get("native_orbit_trial")!=null:
		var preserved:=native_trial_return if not native_trial_return.is_empty() else _native_return_state()
		_commit_state(loaded);native_trial_return=preserved;saving_enabled=false;_close_menu();_apply_system();_native_save_game();_announce("Снимок испытания восстановлен отдельно от основного полёта.");return
	_commit_state(loaded);saving_enabled=true;_close_menu();_apply_system();_save_game();_announce("Резервная копия восстановлена.")
func _apply_settings()->void:
	Engine.max_fps=settings.fps;get_viewport().msaa_3d=settings.msaa();ground_view.set_quality(settings.quality);celestial.set_quality(settings.quality);stick.deadzone=settings.deadzone;presentation_key=""
	if native_ground_view!=null:native_ground_view.set_quality(settings.quality)
	player.set_quality(settings.quality);station.configure(settings.quality);city_view.set_quality(settings.quality)
	if not graphics_return.is_empty():space_environment.configure(ship.STATION,settings.quality)
func _settings_changed()->void:_apply_settings();settings.save_file();_record_event("settings_changed",settings.snapshot())
func _close_settings()->void:settings_panel.hide();_release_inputs();_save_game()

func _unhandled_key_input(event:InputEvent)->void:
	if not event is InputEventKey or not event.pressed or event.echo:return
	if event.physical_keycode==KEY_ESCAPE:
		if settings_panel.visible:_close_settings()
		elif is_instance_valid(active_map):_close_map()
		elif menu.visible:_close_menu()
		else:_show_menu()
		return
	if _blocked():return
	match event.physical_keycode:
		KEY_SPACE:_brake()
		KEY_A:_toggle_auto()
		KEY_D:_dock_action()
		KEY_L:_surface_action()
		KEY_V:_cycle_view()
		KEY_P:_toggle_pause()
		KEY_C:_toggle_control_mode()
		KEY_M:_show_system()
func _notification(what:int)->void:
	if what==NOTIFICATION_APPLICATION_PAUSED or what==NOTIFICATION_APPLICATION_FOCUS_OUT:
		if diagnostics!=null and not automated:diagnostics.lifecycle("paused" if what==NOTIFICATION_APPLICATION_PAUSED else "focus_out")
		active=false;_release_inputs()
		flight_time.interrupt("Приложение неактивно.")
		if ui!=null:_update_flight_controls()
		if ship!=null and (report_export==null or not report_export.is_busy()):_save_game()
	elif what==NOTIFICATION_APPLICATION_RESUMED or what==NOTIFICATION_APPLICATION_FOCUS_IN:
		active=true
		if ui!=null:_update_flight_controls()
		if diagnostics!=null and not automated:diagnostics.lifecycle("resumed" if what==NOTIFICATION_APPLICATION_RESUMED else "focus_in")
	elif what==NOTIFICATION_WM_GO_BACK_REQUEST:
		if menu!=null:
			if settings_panel.visible:_close_settings()
			elif is_instance_valid(active_map):_close_map()
			elif menu.visible:_close_menu()
			else:_show_menu()
	elif what==NOTIFICATION_WM_CLOSE_REQUEST:
		_save_game();get_tree().quit()
func _exit_tree()->void:
	if diagnostics!=null:diagnostics.shutdown(true)
	_finish_information_preparation()
	if is_instance_valid(information_parent) and information_parent.has_method("finish_preparation"):information_parent.finish_preparation()
	if target_worker!=null and target_worker.is_started():target_worker.wait_to_finish()
	if is_instance_valid(active_map) and active_map.has_method("finish_preparation"):active_map.finish_preparation()
	if worker!=null and worker.is_started():worker.wait_to_finish()
	if hatch_worker!=null and hatch_worker.is_started():hatch_worker.wait_to_finish()
	near.finish_preparation()
	if ground_view!=null:ground_view.finish_source_preparation()

func _run_smoke()->void:
	await get_tree().process_frame
	if world.system_id!=44341016 or not world.by_id.has("earth"):push_error("REBUILD SMOKE FAILED: source Sol/Earth");get_tree().quit(1);return
	_toggle_auto()
	for step in range(4000):
		_tick(0.05,Vector2.ZERO,0)
		if ship.docked:break
	if not ship.docked or ship.hull!=100:push_error("REBUILD SMOKE FAILED: actual training auto dock");get_tree().quit(1);return
	if not ship.deliver():push_error("REBUILD SMOKE FAILED: training delivery");get_tree().quit(1);return
	ship.launch();ship.position=Vector3.ZERO;ship.velocity=Vector3.ZERO
	world.focus_id="earth";world.selected_id="earth";world.site_id="site10";_apply_system()
	await _enter_surface()
	if not surface.active or surface.city_data.is_empty():push_error("REBUILD SMOKE FAILED: original city entry");get_tree().quit(1);return
	_toggle_auto()
	for step in range(24000):
		surface.step(0.05,ship,Vector2.ZERO,0)
		if surface.landed:break
	if not surface.landed or ship.hull!=100:push_error("REBUILD SMOKE FAILED: original city landing");get_tree().quit(1);return
	var stored:=SaveStore.new();stored.directory="user://smoke-%d"%OS.get_process_id()
	if not stored.write(_payload()):push_error("REBUILD SMOKE FAILED: save write");get_tree().quit(1);return
	var decoded:Dictionary=stored.load_valid(_decode_state)
	if decoded.is_empty():push_error("REBUILD SMOKE FAILED: save decode");get_tree().quit(1);return
	_commit_state(decoded);_apply_system()
	if not surface.landed or ship.credits!=1800 or int(surface.city_data.profile.model_index)!=84:push_error("REBUILD SMOKE FAILED: progress and native city reload");get_tree().quit(1);return
	if city_view.current_visual()==null:push_error("REBUILD SMOKE FAILED: city mesh integration");get_tree().quit(1);return
	print("REBUILD APP SMOKE PASS: native source Sol/Earth, training auto dock/delivery, original New Moscow84 entry/landing, atomic disk save/reload, persistent original city view")
	await get_tree().process_frame
	get_tree().quit()

scripts/native_orbit_return.gd.source:
extends RefCounted
# Bounded inverse of the native trial's affine outward transfer. It reuses
# the same observed source chart and raw history, not a new 50m trial entry.
const Orbit=preload("res://scripts/native_orbit_trial.gd")
const NativeSurface=preload("res://scripts/native_surface_model.gd")
const Trial=preload("res://scripts/native_landing_trial.gd")
const Phone=preload("res://scripts/source_surface_contact_bridge.gd")
const World=preload("res://scripts/planetary_system.gd")
const Flight=preload("res://scripts/flight_model.gd")
const POLICY:="native-trial-inverse-affine-airborne-return-v1"
const MIN_RETURN_AGL_M:=1000.0
const MAX_RETURN_AGL_M:=30000.0

static func _reject(reason:String)->Dictionary:
	return {"ok":false,"reason":reason,"policy":POLICY,"position_snapped":false,"clock_advanced":false,"fuel_advanced":false,"hp_applied":false}

static func _outbound_surface(orbit:RefCounted,nav:RefCounted)->RefCounted:
	var data:Dictionary=orbit._lineage
	if not data.get("ship") is Dictionary or not data.get("surface") is Dictionary or not data.get("world") is Dictionary:return null
	var source_ship:=Flight.new();var source_world:=World.new();var surface:=NativeSurface.new()
	source_world.configure(nav.current(),World.FULL_LAYOUT)
	if not source_ship.restore(data.ship) or not source_world.restore(data.world) or not surface.restore(data.surface,source_ship,source_world):return null
	return surface

static func prepare_return(orbit:RefCounted,ship:RefCounted,nav:RefCounted,gear:RefCounted,world:RefCounted)->Dictionary:
	if orbit==null or orbit.get_script()!=Orbit or not orbit.is_active() or not orbit._matches(ship,nav,world,gear) or not Orbit._valid(ship,nav,world):return _reject("invalid_bound_orbit_return_owners")
	var source:=_outbound_surface(orbit,nav)
	if source==null or source.landed or source.native_session.phase()!="free":return _reject("outbound_native_lineage_unavailable")
	if str(source.body_id)!=str(world.focus_id) or int(source.native_world().system_id)!=int(world.system_id):return _reject("return_source_identity_changed")
	var cs:=Trial._fork_ship(ship);var cn:RefCounted=nav.fork_runtime();var cg:=Orbit._fork_gear(gear);var cw:=Orbit._fork_world(world)
	if cs==null or cn==null or cg==null or cw==null:return _reject("return_owner_fork_failed")
	var body:Dictionary=cw.by_id[str(cw.focus_id)]
	var rotation:=Orbit.Gas._basis_readonly(cw,body,cn.elapsed_days)
	if rotation.is_empty():return _reject("return_rotation_unavailable")
	var center:Vector3=cw.local_meters(str(cw.focus_id),cn.elapsed_days)
	if not center.is_finite():return _reject("return_center_unavailable")
	var chart:Basis=source.globe.basis_at(source.globe.latitude,source.globe.longitude)
	var relative:=PackedFloat64Array()
	for axis in range(3):relative.append(orbit._position_f64[axis]-float(center[axis]))
	# Both inverse products are scalar-double operations, including the final
	# radius subtraction. Transpose/F32 intermediate vectors lose the residual.
	var bodyfixed:=Phone.to_local_vector(Basis(rotation.basis),relative)
	if bodyfixed.size()!=3:return _reject("return_bodyfixed_projection_unavailable")
	var local:=Phone.to_local_vector(chart,bodyfixed)
	var body_velocity:=Phone.to_local_vector(Basis(rotation.basis),PackedFloat64Array([ship.velocity.x,ship.velocity.y,ship.velocity.z]))
	var velocity:=Phone.to_local_vector(chart,body_velocity)
	if local.size()!=3 or velocity.size()!=3:return _reject("return_chart_projection_unavailable")
	local[1]-=float(source.globe.radius)
	cs.position=Vector3(local[0],local[1],local[2]);cs.velocity=Vector3(velocity[0],velocity[1],velocity[2])
	cs.attitude=(chart.inverse()*Basis(rotation.basis).inverse()*Basis(ship.attitude)).get_rotation_quaternion().normalized()
	cs.surface_mode=true;cs.station_available=false;cs.source_motion_profile=ship.source_motion_profile;cs.clear_source_station()
	if not Trial._finite_ship(cs) or not NativeSurface._native_pose_valid(Orbit._pose(cs)):return _reject("return_pose_outside_supported_range")
	var height:Dictionary=source.height_sample(cs.position.x,cs.position.z)
	if height.is_empty():return _reject("return_outside_observed_native_leaf")
	var agl:float=cs.position.y-float(height.height)-source.clearance(cs)
	if not is_finite(agl) or agl<MIN_RETURN_AGL_M or agl>MAX_RETURN_AGL_M:return _reject("return_height_outside_bounded_airborne_region")
	var speed:=Orbit.Gas.raw_speed(cs.velocity)
	if not speed.get("ok",false):return _reject("return_gear_speed_unavailable")
	var state:Dictionary=cg.state({"flight_state_u8":0,"autopilot_phase_u8":0,"speed_s32":int(speed.speed_s32),"paused":false})
	if not state.get("initialized",false) or not state.has("position_u16"):return _reject("return_gear_unavailable")
	var witness:={"schema":"starfrontier-native-airborne-return-boundary-v1","policy":POLICY,"seconds_f64_hex":Orbit._float(0),"days_before_f64_hex":Orbit._float(nav.elapsed_days),"days_after_f64_hex":Orbit._float(nav.elapsed_days),"outbound_lineage_sha256":Orbit._hash(orbit._lineage),"space_generation":int(orbit._generation),"space_position_f64_hex":NativeSurface._native_floats(Array(orbit._position_f64),8),"space_pose_f32_hex":Orbit._pose(ship),"phone_pose_f32_hex":Orbit._pose(cs),"gear_position_u16":int(state.position_u16)}
	var surface:RefCounted=source.fork_runtime(cs)
	var rebound:Dictionary=surface.rebind_airborne(cs,cw,cn.elapsed_days,int(state.position_u16),witness)
	if not rebound.get("ok",false):return _reject(str(rebound.get("reason","return_native_rebind_failed")))
	if not cn.bind_thermal_ship(cs) or not cn.validate_source_ship(cs):return _reject("return_hp_fuel_owner_mismatch")
	var rounding:Array=[]
	for axis in range(3):rounding.append(absf(local[axis]-float(cs.position[axis])))
	var receipt:Dictionary=Orbit._json({"schema":"starfrontier-native-orbit-return-v1","policy":POLICY,"velocity_policy":Orbit.VELOCITY_POLICY,"system_id":int(cw.system_id),"body_id":str(cw.focus_id),"source_record_hex":str(body.runtime_record_hex),"space_generation":int(orbit._generation),"outbound_lineage_sha256":Orbit._hash(orbit._lineage),"space_position_f64_hex":NativeSurface._native_floats(Array(orbit._position_f64),8),"space_pose_f32_hex":Orbit._pose(ship),"phone_pose_f32_hex":Orbit._pose(cs),"phone_position_ideal_f64_hex":NativeSurface._native_floats(Array(local),8),"phone_velocity_ideal_f64_hex":NativeSurface._native_floats(Array(velocity),8),"phone_position_rounding_error_f64_hex":NativeSurface._native_floats(rounding,8),"days_f64_hex":Orbit._float(cn.elapsed_days),"native_display_agl_m":agl,"airborne_rebind":rebound,"clock_advanced":false,"fuel_advanced":false,"hp_applied":false,"position_snapped":false,"omega_cross_radius_added":false,"full_original_object_bank":false})
	return {"ok":true,"reason":"native_orbit_return_prepared","policy":POLICY,"candidate_ship":cs,"candidate_nav":cn,"candidate_gear":cg,"candidate_world":cw,"candidate_surface":surface,"candidate_orbit":null,"receipt":receipt,"save_after":true}

scripts/native_surface_autopilot.gd.source:
extends RefCounted
# Bounded phone guidance over the existing native-contact interval. This is
# not the complete original FFE autopilot/VM: only Flight's existing controls
# are chosen here. F576/F575 alone decides collision and accepted parking.
const Trial=preload("res://scripts/native_landing_trial.gd")
const Surface=preload("res://scripts/native_surface_model.gd")
const Session=preload("res://scripts/source_natural_contact_session.gd")
const Gear=preload("res://scripts/source_landing_gear_session.gd")
const SCHEMA:="starfrontier-native-surface-autopilot-v1"
const POLICY:="bounded-native-contact-phone-guidance-v1"
const KEYS:=["schema","version","policy","mode","phase","active","steps","elapsed_f64_hex","target_height_f64_hex","launch_recontacts","reason","binding","snapshot_sha256"]
const BINDING_KEYS:=["system_id","body_id","ship_id","source_record_hex","source_generation","raw_body_sha256","raw_parent_sha256","provider_identity","days_f64_hex","phone_pose_f32_hex"]
const LANDING_PHASES:=["gear","align","descent"]
const ASCENT_PHASES:=["launch","align","ascent","braking"]
const RETURN_PHASES:=["entry","braking","gear","align","descent"]
const MAX_RETURN_DESCENT_MPS:=60.0
const RETURN_BRAKE_HEIGHT_M:=600.0
const RETURN_GEAR_HEIGHT_M:=300.0
const MAX_DESCENT_MPS:=4.0
const MIN_DESCENT_MPS:=0.35
const MAX_ASCENT_MPS:=40.0
const ASCENT_CLEARANCE_M:=30.0
const MIN_ASCENT_TARGET_M:=10.0
const MAX_ASCENT_TARGET_M:=30000.0
const ASCENT_HEIGHT_TOLERANCE_M:=0.5
const ASCENT_SPEED_TOLERANCE_MPS:=0.5
const MAX_LEVEL_ERROR_RAD:=0.17453292519943295 # Ten degrees, below F575's actual acceptance cone.
var _saved:Dictionary={}

static func _reject(reason:String)->Dictionary:return {"ok":false,"reason":reason,"guidance_policy":POLICY}
static func _whole(value:Variant,low:int,high:int)->bool:return (value is int or value is float) and is_finite(float(value)) and value==floorf(float(value)) and value>=low and value<=high
static func _digest(bytes:PackedByteArray)->String:
	var hash:=HashingContext.new();hash.start(HashingContext.HASH_SHA256);hash.update(bytes);return hash.finish().hex_encode()
static func _float_hex(value:float)->String:
	var bytes:=PackedByteArray();bytes.resize(8);bytes.encode_double(0,value);return bytes.hex_encode()
static func _float(value:Variant)->float:
	if not Session._hex(value,8):return NAN
	return str(value).hex_decode().decode_double(0)
static func _json(value:Variant)->Variant:return JSON.parse_string(JSON.stringify(value))
static func _valid_scene(ship:RefCounted,nav:RefCounted,surface:RefCounted,allow_destroyed:bool=false)->bool:
	if ship==null or nav==null or surface==null or surface.get_script()!=Surface:return false
	if not surface.is_native_landing_trial() or not ship.surface_mode or ship.docked or not is_finite(ship.hull) or ship.hull<0 or ship.hull>100 or (ship.hull==0 and not allow_destroyed) or not nav.is_source_hyperdrive() or nav.remaining>0:return false
	if surface.native_session.is_pending() or not surface._native_stage.is_empty() or surface.landing or surface.ready_for_orbit or ship.autopilot:return false
	if not ship.position.is_finite() or not ship.velocity.is_finite() or not ship.attitude.is_finite() or absf(ship.attitude.length_squared()-1.0)>0.0001 or not is_finite(nav.elapsed_days) or nav.elapsed_days!=surface._source_days:return false
	return int(surface.native_world().system_id)==int(nav.current_id) and surface.native_world().focus_id==surface.body_id
static func _binding(ship:RefCounted,nav:RefCounted,surface:RefCounted)->Dictionary:
	return _json({"system_id":int(nav.current_id),"body_id":str(surface.body_id),"ship_id":str(ship.ship_id),"source_record_hex":surface._native_source_record.hex_encode(),"source_generation":surface.native_session.generation(),"raw_body_sha256":_digest(surface.native_session.raw_body()),"raw_parent_sha256":_digest(surface.native_session.raw_parent()),"provider_identity":surface.native_provider.snapshot_identity(),"days_f64_hex":_float_hex(nav.elapsed_days),"phone_pose_f32_hex":Surface._native_pose(ship.position,ship.velocity,ship.attitude)})
static func _sealed(data:Dictionary)->Dictionary:
	var result:Dictionary=_json(data);result.erase("snapshot_sha256");result.snapshot_sha256=Session._hash(result);return result

func configure_land(ship:RefCounted,nav:RefCounted,surface:RefCounted)->bool:
	if not _saved.is_empty() or not _valid_scene(ship,nav,surface) or surface.landed:return false
	var height:Dictionary=surface.height_sample(ship.position.x,ship.position.z)
	if height.is_empty() or not is_finite(float(height.get("height",NAN))):return false
	if not _propulsion_ok(ship,surface):return false
	_saved=_sealed({"schema":SCHEMA,"version":1,"policy":POLICY,"mode":"landing","phase":"gear","active":true,"steps":0,"elapsed_f64_hex":_float_hex(0),"target_height_f64_hex":_float_hex(0),"launch_recontacts":0,"reason":"landing_requested","binding":_binding(ship,nav,surface)})
	return true

func configure_ascent(ship:RefCounted,nav:RefCounted,surface:RefCounted,target_height:float=1000.0)->bool:
	if not _saved.is_empty() or not _valid_scene(ship,nav,surface) or not is_finite(target_height) or target_height<MIN_ASCENT_TARGET_M or target_height>MAX_ASCENT_TARGET_M:return false
	var hit:Dictionary=surface.height_sample(ship.position.x,ship.position.z)
	if hit.is_empty() or not _propulsion_ok(ship,surface):return false
	var altitude:float=ship.position.y-float(hit.height)-surface.clearance(ship)
	if not is_finite(altitude) or target_height<=altitude+ASCENT_HEIGHT_TOLERANCE_M:return false
	_saved=_sealed({"schema":SCHEMA,"version":1,"policy":POLICY,"mode":"ascent","phase":"launch" if surface.landed else "ascent","active":true,"steps":0,"elapsed_f64_hex":_float_hex(0),"target_height_f64_hex":_float_hex(target_height),"launch_recontacts":0,"reason":"powered_ascent_requested","binding":_binding(ship,nav,surface)})
	return true

func configure_descent(ship:RefCounted,nav:RefCounted,surface:RefCounted)->bool:
	if not _saved.is_empty() or not _valid_scene(ship,nav,surface) or surface.landed or not _propulsion_ok(ship,surface):return false
	var hit:Dictionary=surface.height_sample(ship.position.x,ship.position.z)
	if hit.is_empty():return false
	var altitude:float=ship.position.y-float(hit.height)-surface.clearance(ship)
	if not is_finite(altitude) or altitude<=RETURN_GEAR_HEIGHT_M or altitude>MAX_ASCENT_TARGET_M:return false
	_saved=_sealed({"schema":SCHEMA,"version":1,"policy":POLICY,"mode":"return_landing","phase":"entry","active":true,"steps":0,"elapsed_f64_hex":_float_hex(0),"target_height_f64_hex":_float_hex(0),"launch_recontacts":0,"reason":"powered_return_descent_requested","binding":_binding(ship,nav,surface)})
	return true

static func _phases(mode_name:String)->Array:
	return ASCENT_PHASES if mode_name=="ascent" else (RETURN_PHASES if mode_name=="return_landing" else LANDING_PHASES)

func is_active()->bool:return bool(_saved.get("active",false))
func phase()->String:return str(_saved.get("phase","idle"))
func mode()->String:return str(_saved.get("mode",""))
func cancel(reason:String="manual_control")->void:
	if _saved.is_empty():return
	_saved.active=false;_saved.phase="cancelled";_saved.reason=reason.left(160);_saved=_sealed(_saved)
func snapshot()->Dictionary:return _saved.duplicate(true) if is_active() else {}
func fork_runtime()->RefCounted:
	var copy:RefCounted=get_script().new();copy._saved=_saved.duplicate(true);return copy

func restore(data:Dictionary,ship:RefCounted,nav:RefCounted,surface:RefCounted)->bool:
	if not _saved.is_empty() or not _valid_scene(ship,nav,surface) or not Session._keys(data,KEYS):return false
	if data.schema!=SCHEMA or not _whole(data.version,1,1) or data.policy!=POLICY or data.mode not in ["landing","ascent","return_landing"] or not data.active is bool or data.active!=true:return false
	if data.phase not in _phases(str(data.mode)) or (data.mode!="ascent" and surface.landed):return false
	if not _whole(data.steps,0,1000000000) or not data.reason is String or data.reason.length()>160 or not data.binding is Dictionary or not Session._keys(data.binding,BINDING_KEYS):return false
	var elapsed:=_float(data.elapsed_f64_hex)
	if not is_finite(elapsed) or elapsed<0 or elapsed>1e9 or (int(data.steps)==0 and elapsed!=0):return false
	var target:=_float(data.target_height_f64_hex)
	if not is_finite(target) or not _whole(data.launch_recontacts,0,60) or (data.mode!="ascent" and (target!=0 or int(data.launch_recontacts)!=0)) or (data.mode=="ascent" and (target<MIN_ASCENT_TARGET_M or target>MAX_ASCENT_TARGET_M)):return false
	if data.mode=="ascent" and surface.landed and data.phase!="launch":return false
	var candidate:Dictionary=_json(data);var checksum:Variant=candidate.snapshot_sha256;candidate.erase("snapshot_sha256")
	if not Session._hex(checksum,32) or Session._hash(candidate)!=checksum or _json(data.binding)!=_binding(ship,nav,surface):return false
	_saved=_json(data);return true

static func _propulsion_ok(ship:RefCounted,surface:RefCounted)->bool:
	if not ship.propulsion_available or not surface.gravity_vector.is_finite():return false
	var available:float=ship.available_acceleration(Vector3.UP)
	return is_finite(available) and available>surface.gravity_vector.length()+0.25

static func _level_controls(ship:RefCounted,seconds:float)->Dictionary:
	var basis:=Basis(ship.attitude);var up:Vector3=basis.y.normalized();var dot:=clampf(up.dot(Vector3.UP),-1,1)
	var angle:=acos(dot);var error:=up.cross(Vector3.UP)
	if error.length_squared()>0.000000000001:error=basis.transposed()*(error.normalized()*angle)
	elif dot<0:error=Vector3(PI,0,0)
	else:error=Vector3.ZERO
	var rate:float=float(ship.profile().turn_rate)
	# Limit by this actual interval so a large step cannot overshoot upright.
	var gain:=minf(2.0,1.0/seconds)
	return {"steering":Vector2(0,clampf(-error.x*gain/rate,-1,1)),"roll":clampf(-error.z*gain*1.2/rate,-1,1),"angle_rad":angle}

func prepare(ship:RefCounted,nav:RefCounted,gear:RefCounted,surface:RefCounted,seconds:float)->Dictionary:
	if not is_active() or mode() not in ["landing","ascent","return_landing"]:return _reject("guidance_inactive")
	if not is_finite(seconds) or seconds<=0 or seconds>1.0:return _reject("invalid_guidance_interval")
	if not _valid_scene(ship,nav,surface) or (mode()!="ascent" and surface.landed) or _binding(ship,nav,surface)!=_saved.binding:return _reject("stale_guidance_binding")
	if gear==null or gear.get_script()!=Gear or gear.snapshot().is_empty():return _reject("invalid_guidance_gear")
	if not _propulsion_ok(ship,surface):return _reject("insufficient_vertical_propulsion")
	var height:Dictionary=surface.height_sample(ship.position.x,ship.position.z)
	if height.is_empty():return _reject("guidance_outside_observed_leaf")
	var altitude:float=ship.position.y-float(height.height)-surface.clearance(ship)
	if not is_finite(altitude):return _reject("nonfinite_guidance_altitude")
	var controls:=_level_controls(ship,seconds);var state:Dictionary=gear.state()
	var available:float=maxf(0.25,ship.acceleration()-surface.gravity_vector.length())
	if mode()=="ascent":
		var target:=_float(_saved.target_height_f64_hex);var error:=target-altitude
		var maximum:=8.0 if altitude<=ASCENT_CLEARANCE_M else MAX_ASCENT_MPS
		var desired:=clampf(error*0.8,-4.0,minf(maximum,sqrt(2.0*available*maxf(error,0))*0.65))
		var phase_name:="launch" if surface.landed else ("braking" if error<100.0 or ship.velocity.y>desired+0.5 else "ascent")
		if not surface.landed and float(controls.angle_rad)>MAX_LEVEL_ERROR_RAD:desired=0.0;phase_name="align"
		return {"ok":true,"reason":"ascent_guidance_prepared","guidance_policy":POLICY,"phase":phase_name,"steering":controls.steering,"roll":controls.roll,"lift":desired/60.0,"target_speed":0.0,"assisted":true,"gear_down":altitude<=ASCENT_CLEARANCE_M,"desired_vertical_mps":desired,"observed_render_altitude_m":altitude,"target_height_m":target,"height_is_orbit":false,"original_contact_decides_landing":true,"pose_written":false}
	if mode()=="return_landing" and altitude>RETURN_GEAR_HEIGHT_M:
		# Choose only an existing thrust command. Start braking above the gear
		# region; actual Flight/fuel limits determine the achieved deceleration.
		var distance:=maxf(0.0,altitude-RETURN_GEAR_HEIGHT_M)
		var maximum:=minf(MAX_RETURN_DESCENT_MPS,maxf(MAX_DESCENT_MPS,sqrt(2.0*available*distance)*0.5))
		var phase_name:="entry" if altitude>RETURN_BRAKE_HEIGHT_M and maximum>=MAX_RETURN_DESCENT_MPS else "braking"
		var desired:=-maximum
		if float(controls.angle_rad)>MAX_LEVEL_ERROR_RAD:desired=0;phase_name="align"
		return {"ok":true,"reason":"return_descent_guidance_prepared","guidance_policy":POLICY,"phase":phase_name,"steering":controls.steering,"roll":controls.roll,"lift":desired/60.0,"target_speed":0.0,"assisted":true,"gear_down":false,"desired_vertical_mps":desired,"observed_render_altitude_m":altitude,"original_contact_decides_landing":true,"pose_written":false}
	var deployed:bool=bool(state.get("deployed",false)) and bool(state.get("requested_down",false))
	var phase_name:="descent" if deployed and float(controls.angle_rad)<=MAX_LEVEL_ERROR_RAD else ("gear" if not deployed else "align")
	var desired_velocity:=-clampf(sqrt(2.0*available*maxf(altitude,0))*0.5,MIN_DESCENT_MPS,MAX_DESCENT_MPS) if phase_name=="descent" else 0.0
	return {"ok":true,"reason":"landing_guidance_prepared","guidance_policy":POLICY,"phase":phase_name,"steering":controls.steering,"roll":controls.roll,"lift":desired_velocity/60.0,"target_speed":0.0,"assisted":true,"gear_down":true,"desired_vertical_mps":desired_velocity,"observed_render_altitude_m":altitude,"original_contact_decides_landing":true,"pose_written":false}

func observe(ship:RefCounted,nav:RefCounted,surface:RefCounted,accepted:Dictionary,seconds:float,planned_phase:String)->bool:
	if not is_active() or not accepted.get("ok",false) or accepted.get("candidate_ship")!=ship or accepted.get("candidate_nav")!=nav or accepted.get("candidate_surface")!=surface or not _valid_scene(ship,nav,surface,bool(accepted.get("destruction_requested",false))):return false
	if not is_finite(seconds) or seconds<=0 or seconds>1.0 or planned_phase not in _phases(mode()):return false
	var candidate:Dictionary=_saved.duplicate(true);candidate.steps=int(candidate.steps)+1;candidate.elapsed_f64_hex=_float_hex(_float(candidate.elapsed_f64_hex)+seconds);candidate.binding=_binding(ship,nav,surface)
	if bool(accepted.get("destruction_requested",false)):
		candidate.active=false;candidate.phase="cancelled";candidate.reason="ship_destroyed"
	elif mode()=="ascent":
		if surface.landed:
			if bool(accepted.get("stage",{}).get("landing_accepted",false)):candidate.launch_recontacts=int(candidate.launch_recontacts)+1
			candidate.phase="launch";candidate.reason="source_park_recontact" if bool(accepted.get("stage",{}).get("landing_accepted",false)) else "source_park_retained"
			if int(candidate.launch_recontacts)>=60:candidate.active=false;candidate.phase="cancelled";candidate.reason="launch_recontact_limit"
		else:
			var hit:Dictionary=surface.height_sample(ship.position.x,ship.position.z)
			if hit.is_empty():return false
			var altitude:float=ship.position.y-float(hit.height)-surface.clearance(ship)
			var offset:float=_float(candidate.target_height_f64_hex)-altitude
			if absf(offset)<=ASCENT_HEIGHT_TOLERANCE_M and absf(ship.velocity.y)<=ASCENT_SPEED_TOLERANCE_MPS and Vector2(ship.velocity.x,ship.velocity.z).length()<=ASCENT_SPEED_TOLERANCE_MPS:
				candidate.active=false;candidate.phase="completed";candidate.reason="powered_ascent_height_reached"
			else:candidate.phase=planned_phase;candidate.reason="powered_ascent_interval_accepted"
	elif surface.landed:
		if surface.native_session.phase()!="parked" or not accepted.get("stage") is Dictionary or not accepted.stage.get("landing_accepted",false):return false
		candidate.active=false;candidate.phase="completed";candidate.reason="original_park_accepted"
	else:candidate.phase=planned_phase;candidate.reason="landing_interval_accepted"
	_saved=_sealed(candidate);return true

func advance(ship:RefCounted,nav:RefCounted,gear:RefCounted,surface:RefCounted,seconds:float)->Dictionary:
	var plan:=prepare(ship,nav,gear,surface,seconds)
	if not plan.get("ok",false):return plan
	var candidate_ship:RefCounted=Trial._fork_ship(ship);var candidate_gear:=Gear.new()
	if candidate_ship==null or not candidate_gear.restore(gear.snapshot()):return _reject("guidance_owner_fork_failed")
	# The existing controller still runs with the real manual Flight input law.
	# Guidance edits control intent only on private candidates, never a pose.
	candidate_ship.assisted=true;candidate_ship.target_speed=0;candidate_ship.autopilot=false
	var request:Dictionary=candidate_gear.command_request(bool(plan.gear_down),Trial._gear_context(candidate_ship,surface))
	if not request.get("ok",false) or not request.get("accepted",false):return _reject("guidance_gear_request_rejected")
	var accepted:=Trial.prepare(candidate_ship,nav,candidate_gear,surface,seconds,plan.steering,float(plan.roll),float(plan.lift))
	if not accepted.get("ok",false):return accepted
	var candidate_pilot:RefCounted=fork_runtime()
	if not candidate_pilot.observe(accepted.candidate_ship,accepted.candidate_nav,accepted.candidate_surface,accepted,seconds,str(plan.phase)):return _reject("guidance_observation_rejected")
	accepted.candidate_pilot=candidate_pilot;accepted.guidance=plan.duplicate(true);accepted.guidance_policy=POLICY
	return accepted

scripts/native_surface_model.gd.source:
extends "res://scripts/surface_model.gd"
# Explicit bounded landing trial. The regular flight/surface revision is never
# replaced. Original integer contact and literal Float32 render leaves remain
# separately witnessed laws; this is not a claim of a universal source mesh.
const NativeProvider=preload("res://scripts/source_native_surface_provider.gd")
const NativeSession=preload("res://scripts/source_natural_contact_session.gd")
const NativeFootprint=preload("res://scripts/source_natural_footprint_probe.gd")
const NativePhone=preload("res://scripts/source_surface_contact_bridge.gd")
const NativeNatural=preload("res://scripts/source_natural_contact.gd")
const NativeFuel=preload("res://scripts/source_fuel_flight_bridge.gd")
const NativeTrace=preload("res://scripts/source_terrain_query_trace.gd")
const NativeGravityFrame=preload("res://scripts/source_fuel_contact.gd")
const NativePhysics=preload("res://scripts/source_physics_bridge.gd")
const NativeFlight=preload("res://scripts/flight_model.gd")
const NATIVE_SCHEMA:="starfrontier-native-surface-trial-v1"
const NATIVE_POLICY:="bounded-native-manual-landing-host-adapter-v1"
const MOTION_POLICY:="phone-delta-over-persistent-source-position-and-q16-velocity-v1"
const SNAPSHOT_KEYS:=["schema","version","policy","motion_policy","active","landed","body_id","system_id","source_record_hex","chart","source_days_f64_hex","phone_pose_f32_hex","phone_legacy_anchor","source_phone_anchor_f32_hex","source_phone_ship_id","orbit_position_f32_hex","orbit_attitude_f32_hex","provider","provider_retained_render_only","session","takeoff_requested","host_park_policy","snapshot_sha256"]
var native_session:RefCounted
var native_provider:RefCounted
var _native_phone_frame:Dictionary={}
var _native_source_record:=PackedByteArray()
var _native_anchor_position:=Vector3.ZERO
var _native_anchor_velocity:=Vector3.ZERO
var _native_anchor_attitude:=Quaternion.IDENTITY
var _native_anchor_ship_id:=""
var _native_stage:Dictionary={}
var _native_takeoff_requested:=false
var _native_provider_retained:=false
var native_last_reason:=""

static func _native_fail(reason:String)->Dictionary:
	return {"ok":false,"reason":reason,"damage_calls":[],"callbacks":[],"hp_applied":false,"clock_advanced":false,"fuel_advanced":false,"ordinary_terrain_fallback":false}
static func _native_hex(value:Variant,count:int)->bool:return NativeSession._hex(value,count)
static func _native_floats(values:Array,width:int)->String:
	var bytes:=PackedByteArray();bytes.resize(values.size()*width)
	for index in range(values.size()):
		if width==4:bytes.encode_float(index*width,float(values[index]))
		else:bytes.encode_double(index*width,float(values[index]))
	return bytes.hex_encode()
static func _native_numbers(hex:String,width:int)->Array:
	var bytes:=hex.hex_decode();var result:Array=[]
	for index in range(bytes.size()/width):result.append(bytes.decode_float(index*width) if width==4 else bytes.decode_double(index*width))
	return result
static func _native_pose(position:Vector3,velocity:Vector3,attitude:Quaternion)->String:
	return _native_floats([position.x,position.y,position.z,velocity.x,velocity.y,velocity.z,attitude.x,attitude.y,attitude.z,attitude.w],4)
static func _native_pose_valid(hex:Variant)->bool:
	if not _native_hex(hex,40):return false
	var values:=_native_numbers(str(hex),4)
	for value:float in values:
		if not is_finite(value) or absf(value)>1e9:return false
	var q:=Quaternion(values[6],values[7],values[8],values[9])
	return q.length_squared()>=0.01 and absf(q.length_squared()-1.0)<0.0001
static func _native_decode_pose(hex:String)->Dictionary:
	var values:=_native_numbers(hex,4)
	return {"position":Vector3(values[0],values[1],values[2]),"velocity":Vector3(values[3],values[4],values[5]),"attitude":Quaternion(values[6],values[7],values[8],values[9])}
static func _native_legacy_pose(ship:RefCounted)->Dictionary:
	return NativeSession._json({"position":[ship.position.x,ship.position.y,ship.position.z],"velocity":[ship.velocity.x,ship.velocity.y,ship.velocity.z],"attitude":[ship.attitude.x,ship.attitude.y,ship.attitude.z,ship.attitude.w]})
static func _native_phone(frame:Dictionary,operands:Dictionary)->Dictionary:
	var values:Array=[]
	for axis:Vector3 in [frame.basis.x,frame.basis.y,frame.basis.z]:
		for component:float in [axis.x,axis.y,axis.z]:values.append(component)
	return {"basis_f64":values,"radius_m":float(frame.globe.radius),"source_uid_u32":int(frame.record.decode_u32(4)),"source_model_index":int(frame.model),"latitude":float(frame.globe.latitude),"longitude":float(frame.globe.longitude),"parent_frame_policy":"isolated-matching-bodyfixed-parent-q31","source_body_parent_index_u8":int(operands.body[0x56]),"source_body_frame_u8":int(operands.body[0x57]),"source_parent_index_u8":int(operands.parent[0x86]),"source_parent_matrix_q31_hex":operands.parent.slice(0,36).hex_encode()}

func is_native_landing_trial()->bool:return active and native_session!=null and native_provider!=null
func native_world()->RefCounted:return _source_system
func _refresh_gravity(ship:RefCounted)->bool:
	# Same isolated source spin helper used by the fuel/atmosphere observers;
	# never advance World.body_spin_by_id merely to sample candidate gravity.
	if globe==null or _source_system==null or not _source_system.by_id.has(body_id):return false
	var body:Dictionary=_source_system.by_id[body_id]
	var rotation:=NativeGravityFrame._basis_readonly(_source_system,body,_source_days)
	if rotation.is_empty():return false
	var geoid:=geoid_height(ship)
	var up_sq:float=pow(float(globe.radius)+geoid,2)-float(ship.position.x)*ship.position.x-float(ship.position.z)*ship.position.z
	if up_sq<=0:return false
	var ll:Array=globe.coordinates_at_height(ship.position.x,ship.position.z,sqrt(up_sq)-float(globe.radius))
	var point:=OrbitLink.direction(ll[0],ll[1])*(float(globe.radius)+geoid)
	var raw:=NativePhysics.relative_from_metres(Basis(rotation.basis)*point)
	if raw.size()!=3:return false
	var sample:=NativePhysics.sample_prepared(int(body.source_a4_packed),raw)
	if sample.is_empty() or not is_finite(float(sample.get("gravity_mps2",NAN))):return false
	var frame:Basis=Basis(rotation.basis)*globe.basis_at(globe.latitude,globe.longitude)
	gravity=float(sample.gravity_mps2);gravity_vector=frame.inverse()*Vector3(sample.acceleration)
	return gravity_vector.is_finite()
func source_city()->bool:return false
# The old Main contact bridge must never consume this surface accidentally.
func uses_source_contact()->bool:return false
func set_source_contact_enabled(_enabled:bool)->void:
	source_contact_enabled=false;_pending_source_contact.clear()
func publish_source_render_state(_state:RefCounted)->void:pass
func pending_source_contact()->Dictionary:return {}
func height_sample(x:float,z:float)->Dictionary:
	# Display AGL uses the uppermost of the emitted literal Float32 triangles.
	# Original contact still tests each source observer against its own leaf.
	return native_provider.height_at(x,z) if native_provider!=null else {}
func height_at(x:float,z:float)->float:
	var hit:=height_sample(x,z)
	return float(hit.height) if not hit.is_empty() else NAN
func raw_height_at(x:float,z:float)->float:return height_at(x,z)
func terrain_key()->String:return NATIVE_SCHEMA+":"+native_provider.snapshot_identity() if native_provider!=null else NATIVE_SCHEMA+":unconfigured"
func recenter(_ship:RefCounted)->void:pass
func pad_position()->Vector3:return Vector3(NAN,NAN,NAN)
func pad_distance(_ship:RefCounted)->float:return INF
func begin_landing(_ship:RefCounted)->bool:
	message="В испытании исходного контакта выполняйте посадку вручную с выпущенными шасси.";return false
func touch_down(_ship:RefCounted)->bool:return false
func begin_departure(_ship:RefCounted)->bool:return false
func begin_ascent(_ship:RefCounted)->bool:return false
func begin_descent(_ship:RefCounted,_system:RefCounted,_days:float)->bool:return false
func resume_descent(_ship:RefCounted)->bool:return false
func enter(_ship:RefCounted,_system:RefCounted,_spherical:=false,_terrain_revision:String=SphereTerrain.CURRENT_REVISION)->bool:return false
func enter_from_orbit(_ship:RefCounted,_system:RefCounted,_days:float)->bool:return false
func leave(_ship:RefCounted,_system:RefCounted=null,_days:=0.0)->bool:return false
func bind_city(_site:Dictionary)->bool:return false

func _native_anchor(ship:RefCounted)->void:
	_native_anchor_position=ship.position;_native_anchor_velocity=ship.velocity;_native_anchor_attitude=ship.attitude;_native_anchor_ship_id=str(ship.ship_id)

func initialize_from(previous:RefCounted,ship:RefCounted,world:RefCounted,days:float,entry_height:float=50.0)->bool:
	if active or previous==null or previous.get("active")!=true or ship==null or world==null or not is_finite(days) or days<0 or days>1e9 or not is_finite(entry_height) or entry_height!=50.0:return false
	if not previous.get("city_data") is Dictionary or not previous.city_data.is_empty() or previous.get("underground")!=null or not previous.get("globe") is SourceTerrain:return false
	var old_globe:RefCounted=previous.globe
	if old_globe.get("configured_ok")!=true or not old_globe.get("source_record") is PackedByteArray or old_globe.source_record.size()!=68:return false
	var target:=str(previous.body_id)
	if target!=str(world.focus_id) or not world.by_id.has(target) or str(world.by_id[target].get("runtime_record_hex",""))!=old_globe.source_record.hex_encode():return false
	if ship.docked or ship.hull<=0 or not _native_pose_valid(_native_pose(ship.position,ship.velocity,ship.attitude)):return false
	var terrain:=SourceTerrain.new();terrain.configure(world,target,"")
	if not terrain.configured_ok:return false
	terrain.latitude=float(old_globe.latitude);terrain.longitude=float(old_globe.longitude)
	# Only metadata/frame comes from the old revision. No old sampled height is
	# consulted and no existing play session is translated to this source field.
	globe=terrain;body_id=target;_source_system=world;_source_days=days;active=true
	var prepared:=NativeFootprint._prepare(self,ship,{})
	if not prepared.get("ok",false):active=false;return false
	var initial:=NativeFootprint._operands(prepared,0)
	if initial.is_empty():active=false;return false
	_native_phone_frame=_native_phone(prepared,initial);_native_source_record=prepared.record.duplicate()
	var direction:=PackedInt64Array();var basis:Basis=prepared.basis
	var length:=sqrt(float(basis.y.x)*basis.y.x+float(basis.y.y)*basis.y.y+float(basis.y.z)*basis.y.z)
	for value:float in [basis.y.x,basis.y.y,basis.y.z]:direction.append(clampi(roundi(value/length*2147483647.0),-2147483647,2147483647))
	var entry_hash:=NativeSession._hash({"system_id":int(world.system_id),"body_id":target,"source_record_hex":_native_source_record.hex_encode(),"phone_frame":_native_phone_frame,"entry_policy":"explicit-new-trial-signed-native-root-plus-50m"})
	var root:=NativeProvider.prepare_root(_native_source_record,_native_phone_frame,direction,{"generation":0,"request_token":entry_hash,"request_sha256":entry_hash})
	if not root.get("ok",false):active=false;native_last_reason=str(root.get("reason","native_root_unavailable"));return false
	var provider:RefCounted=root.provider;var anchor:Dictionary=provider.root_anchor();var local:Variant=anchor.get("local_point")
	if not local is PackedFloat64Array or local.size()!=3:active=false;return false
	var x:=float(Vector3(local[0],0,local[2]).x);var z:=float(Vector3(local[0],0,local[2]).z)
	var ground:Dictionary=provider.height_at(x,z,0)
	if ground.is_empty():active=false;native_last_reason="entry_float32_anchor_outside_literal_leaf";return false
	var original_pose:=_native_pose(ship.position,ship.velocity,ship.attitude)
	ship.position=Vector3(x,float(ground.height)+clearance(ship)+entry_height,z);ship.velocity=Vector3.ZERO;ship.attitude=Quaternion.IDENTITY
	prepared=NativeFootprint._prepare(self,ship,{})
	var operands:=NativeFootprint._operands(prepared,0) if prepared.get("ok",false) else {}
	var session:=NativeSession.new()
	var binding:={"system_id":int(world.system_id),"parent_id":target,"source_record_hex":_native_source_record.hex_encode(),"coordinate_policy":NativeSession.COORDINATE_POLICY,"history_policy":NativeSession.HISTORY_POLICY}
	if operands.is_empty() or not session.configure(operands.body,operands.parent,NativeNatural._globals({}),binding) or not _refresh_gravity(ship):
		var old:=_native_decode_pose(original_pose);ship.position=old.position;ship.velocity=old.velocity;ship.attitude=old.attitude;active=false;return false
	native_provider=provider;native_session=session;_source_render_ship=ship;_native_anchor(ship)
	orbit_position=previous.orbit_position;orbit_attitude=previous.orbit_attitude;kind=str(previous.kind);seed_value=int(previous.seed_value)
	landed=false;landing=false;taking_off=false;flight_phase="";extended_flight=false;ready_for_orbit=false;frame_index=0
	ship.surface_mode=true;ship.station_available=false;ship.autopilot=false;ship.target_speed=0;ship.assisted=true;ship.source_motion_profile=false
	render_position=ship.position;render_velocity=ship.velocity;_source_render_clearance=altitude(ship)
	message="Испытание исходной посадки: ручное управление, шасси, ограниченный участок исходного рельефа."
	native_last_reason="native_trial_initialized_from_signed_root";return true

func fork_runtime(ship:RefCounted=null)->RefCounted:
	var copy:RefCounted=get_script().new()
	for property:Dictionary in get_property_list():
		if int(property.usage)&PROPERTY_USAGE_SCRIPT_VARIABLE:
			var key:=str(property.name);var value:Variant=get(key)
			if key=="native_session":value=native_session.fork_runtime() if native_session!=null else null
			elif value is Dictionary or value is Array:value=value.duplicate(true)
			elif value is PackedByteArray or value is PackedInt64Array or value is PackedFloat64Array:value=value.duplicate()
			copy.set(key,value)
	copy._source_render_ship=ship if ship!=null else _source_render_ship
	return copy

func take_off(ship:RefCounted)->bool:
	if not is_native_landing_trial() or not landed or native_session.phase()!="parked" or ship.hull<=0 or not ship.propulsion_available:return false
	var valid_lift:Vector3=ship.filter_propulsive_delta(Vector3.UP)
	if not valid_lift.is_finite() or valid_lift.dot(Vector3.UP)<=0:return false
	# A request arms the next powered interval. It never teleports or rotates.
	_native_takeoff_requested=true;message="Взлёт запрошен. Подъём начнётся при доступной тяге.";return true

func _native_operands(ship:RefCounted,gear:int)->Dictionary:
	var frame:=NativeFootprint._prepare(self,ship,{})
	if not frame.get("ok",false):return _native_fail(str(frame.get("reason","invalid_native_phone_frame")))
	var operands:=NativeFootprint._operands(frame,gear)
	if operands.is_empty() or _native_anchor_ship_id!=str(ship.ship_id):return _native_fail("invalid_or_changed_native_trial_ship")
	if _native_phone(frame,operands)!=_native_phone_frame or operands.parent!=native_session.raw_parent():return _native_fail("native_trial_chart_or_parent_changed")
	var old:PackedByteArray=native_session.raw_body();var candidate:PackedByteArray=operands.body
	var move:=NativePhone.to_bodyfixed_vector(frame.basis,ship.position-_native_anchor_position)
	var delta_velocity:=NativePhone.to_bodyfixed_vector(frame.basis,ship.velocity-_native_anchor_velocity)
	if move.size()!=3 or delta_velocity.size()!=3:return _native_fail("native_motion_delta_undefined")
	for axis in range(3):
		var delta_raw:=roundi(move[axis]/SourceUnits.METRES_PER_RAW)
		var position_raw:int=old.decode_s64(0x3e+axis*8)
		if absf(float(position_raw))+absf(float(delta_raw))>4503599627370495.0:return _native_fail("native_position_delta_overflow")
